function calculateCostUsd(provider, model, inputTokens, outputTokens) {
  const providerCosts = AI_PROVIDER_COSTS[provider];
  let costs = providerCosts?.[model];
  if (!costs) {
    for (const p of Object.values(AI_PROVIDER_COSTS)) {
      const found = p[model];
      if (found) {
        costs = found;
        break;
      }
    }
  }
  if (!costs) {
    const fallbackCosts = {
      anthropic: { inputPerMillion: 3, outputPerMillion: 15 },
      openai: { inputPerMillion: 2.5, outputPerMillion: 10 },
      gemini: { inputPerMillion: 0.15, outputPerMillion: 0.6 }
    };
    costs = fallbackCosts[provider];
  }
  if (!costs) return 0;
  return inputTokens / 1e6 * costs.inputPerMillion + outputTokens / 1e6 * costs.outputPerMillion;
}
function calculateCreditsFromCost(costUsd, marginMultiplier = 1.5) {
  return Math.ceil(costUsd * CREDITS_PER_USD * marginMultiplier);
}
