// src/modules/agents/dynamic-avatar-state.ts
function buildArcOverviewBlock(arc) {
  const lines = [];
  lines.push(`## \u2501\u2501\u2501 ARCO EMOCIONAL DA CAMPANHA \u2501\u2501\u2501`);
  lines.push(`> ${arc.arcSummary}`);
  lines.push(``);
  lines.push(`### PROGRESS\xC3O EMOCIONAL \u2014 FASE A FASE`);
  arc.phases.forEach((p) => {
    lines.push(
      `**${p.name}** (beliefLevel: ${p.beliefLevel}/100 | resist\xEAncia: ${p.resistanceLevel}/100 | temp: ${p.buyingTemperature}) \u2014 "${p.mainInternalQuestion}"`
    );
  });
  lines.push(``);
  if (arc.emotionalCoherenceRules?.length) {
    lines.push(`### REGRAS DE COER\xCANCIA EMOCIONAL (todos os agentes devem seguir)`);
    arc.emotionalCoherenceRules.forEach((r, i) => lines.push(`${i + 1}. ${r}`));
    lines.push(``);
  }
  if (arc.criticalTransitions?.length) {
    lines.push(`### TRANSI\xC7\xD5ES CR\xCDTICAS \u2014 PONTOS DE RISCO`);
    arc.criticalTransitions.forEach((t) => {
      lines.push(`**${t.from} \u2192 ${t.to}:** ${t.risk}`);
      lines.push(`  \u2192 Solu\xE7\xE3o: ${t.solution}`);
    });
    lines.push(``);
  }
  if (arc.winningPatternHypothesis) {
    lines.push(`**Hip\xF3tese de padr\xE3o emocional vencedor:** ${arc.winningPatternHypothesis}`);
    lines.push(``);
  }
  lines.push(`---
`);
  return lines.join("\n");
}
function buildArcBlockFromIntakeData(intakeData) {
  const arc = intakeData["_emotionalArc"];
  if (!arc?.phases?.length) return "";
  return buildArcOverviewBlock(arc);
}

// src/modules/agents/profile-injector.ts
function buildPsychologicalProfileBlock(intakeData) {
  const raw = intakeData["_psychologicalProfile"];
  if (!raw || typeof raw !== "object") return "";
  const p = raw;
  const parts = [];
  parts.push(`## \u2501\u2501\u2501 PERFIL PSICOL\xD3GICO DO AVATAR \u2501\u2501\u2501`);
  parts.push(
    `> S\xEDntese psicol\xF3gica profunda gerada ap\xF3s o briefing. Representa o perfil real do avatar \u2014 n\xE3o o que o produtor imagina, mas o que os dados revelaram. Este perfil governa TODA decis\xE3o de copy, posicionamento e estrat\xE9gia.`
  );
  if (p.insightEstrategico) {
    parts.push(`
**Insight estrat\xE9gico central:** ${p.insightEstrategico}`);
  }
  if (p.headlinePotencial) {
    parts.push(`**Headline potencial derivada do perfil:** "${p.headlinePotencial}"`);
  }
  if (p.linguagem) {
    parts.push(`
### MAPA DE LINGUAGEM`);
    if (p.linguagem.palavrasChave?.length) {
      parts.push(
        `**Palavras/frases exatas do avatar** (use no copy \u2014 s\xE3o da voz DELE, n\xE3o da sua): ` + p.linguagem.palavrasChave.join(" | ")
      );
    }
    if (p.linguagem.palavrasBanidas?.length) {
      parts.push(
        `**Palavras banidas** (NUNCA use \u2014 soam falsas ou irritantes para este avatar): ` + p.linguagem.palavrasBanidas.join(" | ")
      );
    }
    if (p.linguagem.metaforasDominantes?.length) {
      parts.push(
        `**Met\xE1foras dominantes do avatar** (como ele pensa sobre o problema): ` + p.linguagem.metaforasDominantes.join(" | ")
      );
    }
    if (p.linguagem.tomPreferido) {
      parts.push(`**Tom preferido:** ${p.linguagem.tomPreferido}`);
    }
  }
  if (p.desejo) {
    parts.push(`
### MAPA DE DESEJO`);
    if (p.desejo.superficial) {
      parts.push(`**Desejo declarado** (o que diz que quer): ${p.desejo.superficial}`);
    }
    if (p.desejo.real) {
      parts.push(`**Desejo real** (motiva\xE7\xE3o raiz por baixo): ${p.desejo.real}`);
    }
    if (p.desejo.proibido) {
      parts.push(`**Desejo proibido** (nunca admite em voz alta \u2014 mas aparece nos detalhes): ${p.desejo.proibido}`);
    }
    if (p.desejo.identitario) {
      parts.push(`**Desejo identit\xE1rio** (em quem quer se tornar atrav\xE9s do produto): ${p.desejo.identitario}`);
    }
  }
  if (p.objecao) {
    parts.push(`
### MAPA DE OBJE\xC7\xC3O`);
    if (p.objecao.principal) {
      parts.push(`**Obje\xE7\xE3o principal** (a que mais bloqueia a compra \u2014 destrua-a primeiro): ${p.objecao.principal}`);
    }
    if (p.objecao.secundarias?.length) {
      parts.push(`**Obje\xE7\xF5es secund\xE1rias:** ${p.objecao.secundarias.join(" | ")}`);
    }
    if (p.objecao.geradoraDeConfianca) {
      parts.push(`**O que gera confian\xE7a para ESTE avatar especificamente:** ${p.objecao.geradoraDeConfianca}`);
    }
    if (p.objecao.destruidoraDeCredibilidade) {
      parts.push(`**O que destr\xF3i credibilidade instantaneamente:** ${p.objecao.destruidoraDeCredibilidade}`);
    }
  }
  if (p.identidade) {
    parts.push(`
### MAPA DE IDENTIDADE`);
    if (p.identidade.querProvar) {
      parts.push(`**Quer provar para si mesmo:** ${p.identidade.querProvar}`);
    }
    if (p.identidade.querEvitar) {
      parts.push(`**Quer evitar ser chamado de / percebido como:** ${p.identidade.querEvitar}`);
    }
    if (p.identidade.querSeTornar) {
      parts.push(`**Identidade aspiracional** (em quem quer se tornar): ${p.identidade.querSeTornar}`);
    }
    if (p.identidade.querDeixarDeSer) {
      parts.push(`**Identidade atual que quer abandonar:** ${p.identidade.querDeixarDeSer}`);
    }
  }
  if (p.emocao) {
    parts.push(`
### MAPA EMOCIONAL`);
    if (p.emocao.dominante) {
      parts.push(`**Emo\xE7\xE3o dominante:** ${p.emocao.dominante}`);
    }
    if (p.emocao.gatilhoPrincipal) {
      parts.push(`**Gatilho que a ativa:** ${p.emocao.gatilhoPrincipal}`);
    }
    if (p.emocao.acordadaAs23h) {
      parts.push(`**O que o mant\xE9m acordado \xE0s 23h:** ${p.emocao.acordadaAs23h}`);
    }
    if (p.emocao.nuncaAdmiteEmVozAlta) {
      parts.push(`**O que sente mas nunca admite em voz alta:** ${p.emocao.nuncaAdmiteEmVozAlta}`);
    }
  }
  if (p.mercado) {
    parts.push(`
### MAPA DE MERCADO`);
    if (p.mercado.inimigo) {
      parts.push(`**Inimigo do avatar** (o que/quem culpa pelo problema que ainda tem): ${p.mercado.inimigo}`);
    }
    if (p.mercado.mentiraDominante) {
      parts.push(`**Mentira dominante do mercado** (promessa que ele j\xE1 aprendeu a desconfiar): ${p.mercado.mentiraDominante}`);
    }
    if (p.mercado.linguagemDominante) {
      parts.push(`**Linguagem dominante no mercado:** ${p.mercado.linguagemDominante}`);
    }
    if (p.mercado.maturidade) {
      parts.push(`**Maturidade do avatar:** ${p.mercado.maturidade}`);
    }
  }
  const validIncoerencias = (p.incoerencias ?? []).filter(Boolean);
  if (validIncoerencias.length) {
    parts.push(`
### INCOER\xCANCIAS DETECTADAS NO BRIEFING`);
    parts.push(
      validIncoerencias.map((i) => `\u26A0\uFE0F ${i}`).join("\n") + `
\u2192 Use essas incoer\xEAncias para calibrar o posicionamento. N\xE3o confronte \u2014 clarify atrav\xE9s do copy.`
    );
  }
  const voiceFile = intakeData["_avatarVoiceFile"];
  if (voiceFile && typeof voiceFile === "string" && voiceFile.length > 100) {
    parts.push(`
### ARQUIVO DE VOZ DO AVATAR`);
    parts.push(
      `> Este documento foi escrito NA VOZ DO AVATAR \u2014 mon\xF3logo interno em primeira pessoa.
> Use as frases, express\xF5es e emo\xE7\xF5es deste documento DIRETAMENTE no copy.
> Frases levantadas daqui t\xEAm convers\xE3o muito superior \xE0 copy inventada.
> T\xE9cnica Carlton/Kennedy: o cliente deve ler o copy e pensar "como voc\xEA sabia exatamente o que eu sinto?"`
    );
    parts.push(`
${voiceFile}`);
    parts.push(``);
  }
  const arcBlock = buildArcBlockFromIntakeData(intakeData);
  if (arcBlock) {
    parts.push(arcBlock);
  }
  parts.push(
    `
> **INSTRU\xC7\xC3O CR\xCDTICA ANTES DE ESCREVER QUALQUER FRASE:**
> 1. Esta frase usa as palavras exatas do avatar (mapa de linguagem ou arquivo de voz)?
> 2. Toca no desejo REAL (n\xE3o superficial)?
> 3. Endere\xE7a ou dissolve a obje\xE7\xE3o principal?
> 4. Apela para a identidade que ele quer TER, n\xE3o para quem ele \xE9 agora?
> Se n\xE3o: reescreva antes de entregar.`
  );
  parts.push(`
---
`);
  return parts.join("\n");
}

